cd /tmp/sv-7d0b5c94739f416db1361fc23d4a9297/moderate-version-conflicts && dotnet list package --format json > after-cpm-packages.json 2>/dev/null && python3 -c "
import json
with open('baseline-packages.json') as f: before = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def get_pkgs(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        pkgs = {}
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                pkgs[pkg['id']] = pkg.get('resolvedVersion', pkg.get('requestedVersion',''))
        result[name] = pkgs
    return result

b = get_pkgs(before)
a = get_pkgs(after)
changes = []
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(pkg, 'N/A')
        av = ap.get(pkg, 'N/A')
        if bv != av:
            changes.append((proj, pkg, bv, av))

if changes:
    print('CHANGES:')
    for proj, pkg, bv, av in changes:
        print(f'  {proj}: {pkg} {bv} -> {av}')
else:
    print('No changes - version neutral')
"

